import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { ArrowLeft } from 'lucide-react';
import VirtualInterviewer from './VirtualInterviewer';

interface VoiceInterviewProps {
  onBack: () => void;
}

const VoiceInterview: React.FC<VoiceInterviewProps> = ({ onBack }) => {
  const [session, setSession] = useState<any>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [audioUrl, setAudioUrl] = useState<string>('');
  const [transcript, setTranscript] = useState<string>('');
  const [interviewerState, setInterviewerState] = useState<string>('idle');
  const [profile, setProfile] = useState<any>(null);
  const [resumeFile, setResumeFile] = useState<File | null>(null);
  const [interviewType, setInterviewType] = useState('Technical Interview');
  const [targetRole, setTargetRole] = useState('AI Engineer');
  const [difficulty, setDifficulty] = useState('Mid-Level');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [mediaRecorder, setMediaRecorder] = useState<MediaRecorder | null>(null);
  const [recordedChunks, setRecordedChunks] = useState<Blob[]>([]);
  const [recordingTime, setRecordingTime] = useState(0);
  const [startTime, setStartTime] = useState<number | null>(null);

  // Recording timer effect
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isRecording) {
      interval = setInterval(() => {
        setRecordingTime(prev => prev + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isRecording]);

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);

      recorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          setRecordedChunks(prev => [...prev, event.data]);
        }
      };

      recorder.onstop = () => {
        const blob = new Blob(recordedChunks, { type: 'audio/webm' });
        const audioFile = new File([blob], 'recording.webm', { type: 'audio/webm' });
        submitAnswer(audioFile);
        setRecordedChunks([]);
        stream.getTracks().forEach(track => track.stop());
      };

      setMediaRecorder(recorder);
      recorder.start();
      setIsRecording(true);
      setRecordingTime(0);
    } catch (err) {
      console.error('Error accessing microphone:', err);
      setError('Could not access microphone. Please allow microphone access.');
    }
  };

  const stopRecording = () => {
    if (mediaRecorder && isRecording) {
      mediaRecorder.stop();
      setIsRecording(false);
    }
  };

  const handleResumeUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setResumeFile(file);
      setLoading(true);
      setError(null);
      const formData = new FormData();
      formData.append('file', file);

      try {
        const response = await axios.post('http://localhost:8000/api/interview/upload-resume', formData);
        setProfile(response.data.profile);
      } catch (error: any) {
        console.error('Error uploading resume:', error);
        setError('Failed to upload resume: ' + (error.response?.data?.detail || error.message));
      } finally {
        setLoading(false);
      }
    }
  };

  const startVoiceInterview = async () => {
    if (!profile) {
      setError('Please upload a resume first');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      console.log('Starting voice interview with profile:', profile);
      const response = await axios.post('http://localhost:8000/api/interview/voice/start', {
        profile,
        interview_type: interviewType,
        target_role: targetRole,
        difficulty: difficulty,
        total_questions: 5,
        enable_tts: false,  // Disabled to avoid torch loading delay
        enable_stt: false   // Disabled to avoid torch loading delay
      });
      console.log('Voice interview started:', response.data);
      setSession(response.data.session);
      setStartTime(Date.now());

      // Auto-play first question
      if (response.data.session.current_question) {
        playQuestionAudio(response.data.session.current_question);
      } else {
        setInterviewerState('listening');
      }
    } catch (error: any) {
      console.error('Error starting interview:', error);
      setError('Failed to start interview: ' + (error.response?.data?.detail || error.message));
    } finally {
      setLoading(false);
    }
  };

  const playQuestionAudio = async (text: string) => {
    setLoading(true);
    setError(null);
    setInterviewerState('speaking'); // Switch to SPEAKING when TTS starts

    try {
      console.log('Requesting TTS for:', text);
      const response = await axios.post('http://localhost:8000/api/interview/tts', text, {
        responseType: 'blob',
        headers: {
          'Content-Type': 'text/plain'
        }
      });

      console.log('TTS response received, size:', response.data.size);
      const blob = new Blob([response.data], { type: 'audio/wav' });
      const url = URL.createObjectURL(blob);
      setAudioUrl(url);

      const audio = new Audio(url);
      audio.onended = () => {
        console.log('Audio ended, switching to LISTENING');
        setInterviewerState('listening'); // Switch to LISTENING when audio ends
      };
      audio.onerror = (e) => {
        console.error('Audio playback error:', e);
        setError('Failed to play audio. Browser may not support this format.');
        setInterviewerState('listening');
      };

      await audio.play();
      console.log('Audio playing successfully');
    } catch (error: any) {
      console.error('Error playing audio:', error);
      setError('TTS failed: ' + (error.response?.data?.detail || error.message));
      setInterviewerState('listening');
    } finally {
      setLoading(false);
    }
  };

  const submitAnswer = async (audioFile?: File, textAnswer?: string) => {
    setInterviewerState('thinking'); // Switch to THINKING when candidate submits answer
    setLoading(true);
    setError(null);

    try {
      console.log('Submitting answer, audioFile:', !!audioFile, 'textAnswer:', !!textAnswer);
      let finalTextAnswer = textAnswer;

      if (audioFile) {
        // Upload audio and get transcription
        console.log('Uploading audio for STT...');
        const formData = new FormData();
        formData.append('file', audioFile);
        try {
          const sttResponse = await axios.post('http://localhost:8000/api/interview/stt', formData);
          console.log('STT response:', sttResponse.data);
          setTranscript(sttResponse.data.text);
          finalTextAnswer = sttResponse.data.text;
        } catch (sttError: any) {
          console.error('STT failed:', sttError);
          setError('Speech-to-text failed: ' + (sttError.response?.data?.detail || sttError.message));
          setInterviewerState('listening');
          setLoading(false);
          return;
        }
      }

      if (!finalTextAnswer) {
        setError('No answer to submit. Please provide text or audio.');
        setInterviewerState('listening');
        setLoading(false);
        return;
      }

      console.log('Submitting answer to voice endpoint...');
      const response = await axios.post('http://localhost:8000/api/interview/voice/answer', {
        session: session,
        audio_file: audioFile ? 'temp_audio.wav' : undefined,
        text_answer: finalTextAnswer
      });

      console.log('Answer submitted, response:', response.data);
      setSession(response.data.session);

      if (response.data.session.is_completed) {
        setInterviewerState('completed');
      } else {
        // Switch to SPEAKING when next question is ready
        setInterviewerState('speaking');
        // Auto-play next question audio
        if (response.data.session.current_question) {
          playQuestionAudio(response.data.session.current_question);
        } else {
          setInterviewerState('listening');
        }
      }
    } catch (error: any) {
      console.error('Error submitting answer:', error);
      setError('Failed to submit answer: ' + (error.response?.data?.detail || error.message));
      setInterviewerState('listening');
    } finally {
      setLoading(false);
    }
  };

  const getDuration = () => {
    if (!startTime) return '0:00';
    const elapsed = Math.floor((Date.now() - startTime) / 1000);
    const mins = Math.floor(elapsed / 60);
    const secs = elapsed % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 via-slate-900 to-gray-900">
      {/* Back button - minimal */}
      <button 
        onClick={onBack} 
        className="absolute top-4 left-4 text-white/60 hover:text-white z-50 text-sm"
      >
        ← Exit
      </button>

      {/* Setup Screen */}
      {!session && (
        <div className="min-h-screen flex items-center justify-center p-8">
          <div className="bg-white/5 backdrop-blur-lg rounded-2xl p-8 max-w-md w-full border border-white/10">
            <h1 className="text-2xl font-bold text-white mb-6 text-center">🎙️ Voice Interview</h1>

            {error && (
              <div className="bg-red-500/20 border border-red-500/50 p-3 rounded-lg mb-4">
                <p className="text-red-300 text-sm">{error}</p>
                <button onClick={() => setError(null)} className="text-red-400 text-xs mt-1 underline">Dismiss</button>
              </div>
            )}

            {!profile && (
              <div className="space-y-4">
                <div>
                  <label className="block text-white/80 text-sm mb-2">Upload Resume</label>
                  <input
                    type="file"
                    accept=".pdf,.docx,.txt"
                    onChange={handleResumeUpload}
                    className="w-full text-white/80 text-sm file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-semibold file:bg-blue-500 file:text-white hover:file:bg-blue-600"
                  />
                </div>
              </div>
            )}

            {profile && !session && (
              <div className="space-y-4">
                <div className="bg-green-500/20 border border-green-500/50 p-3 rounded-lg">
                  <p className="text-green-300 text-sm">✅ Resume analyzed</p>
                  <p className="text-white/70 text-xs mt-1">{profile.candidate_name}</p>
                </div>

                <div>
                  <label className="block text-white/80 text-sm mb-2">Interview Type</label>
                  <select
                    value={interviewType}
                    onChange={(e) => setInterviewType(e.target.value)}
                    className="w-full p-2 rounded-lg bg-white/10 text-white/80 border border-white/20 text-sm"
                  >
                    <option value="Technical Interview">Technical Interview</option>
                    <option value="Project Defense">Project Defense</option>
                    <option value="Behavioral Interview">Behavioral Interview</option>
                  </select>
                </div>

                <div>
                  <label className="block text-white/80 text-sm mb-2">Target Role</label>
                  <input
                    type="text"
                    value={targetRole}
                    onChange={(e) => setTargetRole(e.target.value)}
                    className="w-full p-2 rounded-lg bg-white/10 text-white/80 border border-white/20 text-sm"
                  />
                </div>

                <div>
                  <label className="block text-white/80 text-sm mb-2">Difficulty</label>
                  <select
                    value={difficulty}
                    onChange={(e) => setDifficulty(e.target.value)}
                    className="w-full p-2 rounded-lg bg-white/10 text-white/80 border border-white/20 text-sm"
                  >
                    <option value="Entry-Level">Entry-Level</option>
                    <option value="Mid-Level">Mid-Level</option>
                    <option value="Senior">Senior</option>
                  </select>
                </div>

                <button
                  onClick={startVoiceInterview}
                  disabled={loading}
                  className="w-full bg-blue-500 hover:bg-blue-600 text-white py-3 rounded-lg font-semibold text-sm disabled:opacity-50"
                >
                  {loading ? '⏳ Starting...' : '🚀 Start Interview'}
                </button>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Interview Screen - Immersive */}
      {session && (
        <div className="min-h-screen flex flex-col">
          {/* Subtle Status Bar */}
          <div className="absolute top-4 left-1/2 transform -translate-x-1/2 flex items-center gap-6 text-white/60 text-xs z-50">
            <span>{interviewType}</span>
            <span>•</span>
            <span>{targetRole}</span>
            <span>•</span>
            <span>Q {session.current_question_index + 1}/{session.total_questions}</span>
            <span>•</span>
            <span>{getDuration()}</span>
          </div>

          {/* Main Interview Area */}
          <div className="flex-1 flex flex-col items-center justify-center p-4">
            {/* Virtual Interviewer - Centered and Prominent */}
            <div className="mb-6">
              <VirtualInterviewer
                state={interviewerState === 'processing' ? 'thinking' : interviewerState}
                onSpeakComplete={() => setInterviewerState('listening')}
              />
            </div>

            {/* Current Question - Subtle */}
            {session && !session.is_completed && (
              <div className="max-w-2xl w-full text-center">
                <p className="text-white/80 text-lg leading-relaxed">
                  "{session.current_question}"
                </p>
              </div>
            )}
          </div>

          {/* Minimal Input Area - Bottom */}
          {session && !session.is_completed && (
            <div className="p-6 border-t border-white/10 bg-black/20">
              <div className="max-w-2xl mx-auto">
                {/* Recording Button - Prominent */}
                <div className="flex justify-center mb-4">
                  {!isRecording ? (
                    <button
                      onClick={startRecording}
                      disabled={loading}
                      className="flex items-center gap-2 bg-red-500 hover:bg-red-600 text-white px-8 py-4 rounded-full font-semibold disabled:opacity-50 text-lg"
                    >
                      <span className="text-2xl">🎙️</span> Record Answer
                    </button>
                  ) : (
                    <button
                      onClick={stopRecording}
                      className="flex items-center gap-2 bg-red-600 hover:bg-red-700 text-white px-8 py-4 rounded-full font-semibold animate-pulse text-lg"
                    >
                      <span className="text-2xl">⏹️</span> Stop
                      <span className="bg-white/20 px-3 py-1 rounded-full text-sm">
                        {Math.floor(recordingTime / 60)}:{(recordingTime % 60).toString().padStart(2, '0')}
                      </span>
                    </button>
                  )}
                </div>

                {/* Text Input - Minimal */}
                <div className="flex gap-2">
                  <textarea
                    value={transcript}
                    onChange={(e) => setTranscript(e.target.value)}
                    placeholder="Or type your answer..."
                    className="flex-1 p-3 rounded-lg bg-white/10 text-white/80 border border-white/20 focus:border-white/40 focus:outline-none text-sm resize-none"
                    rows={2}
                  />
                  <button
                    onClick={() => {
                      if (transcript.trim()) {
                        setLoading(true);
                        submitAnswer(undefined, transcript);
                      }
                    }}
                    disabled={!transcript.trim() || loading}
                    className="bg-green-500 hover:bg-green-600 text-white px-6 rounded-lg font-semibold text-sm disabled:opacity-50"
                  >
                    Send
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Completion Screen */}
          {session && session.is_completed && (
            <div className="flex-1 flex items-center justify-center p-8">
              <div className="bg-white/5 backdrop-blur-lg rounded-2xl p-8 max-w-md w-full border border-white/10 text-center">
                <h2 className="text-3xl font-bold text-white mb-4">🎉 Interview Complete</h2>
                {session.report && (
                  <div className="text-white/80 space-y-3 mb-6">
                    <p><strong className="text-white">Score:</strong> {session.report.overall_score || 'N/A'}</p>
                    <p><strong className="text-white">Strengths:</strong> {session.report.strengths || 'N/A'}</p>
                    <p><strong className="text-white">Improvement:</strong> {session.report.areas_for_improvement || 'N/A'}</p>
                  </div>
                )}
                <button
                  onClick={onBack}
                  className="bg-blue-500 hover:bg-blue-600 text-white px-8 py-3 rounded-lg font-semibold"
                >
                  Back to Dashboard
                </button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default VoiceInterview;
